cat > /tmp/analysis/similarity_check.py <<'EOF'
import pyarrow.parquet as pq, sys, re, collections, math
train_p,val_p=sys.argv[1],sys.argv[2]
tt=pq.read_table(train_p,columns=['prompt','extra_info']).to_pylist()
vt=pq.read_table(val_p,columns=['prompt','extra_info','data_source']).to_pylist()
def train_q(c):
    i=c.find('\n\n',c.find('Answer:'))
    j=c.rfind('\n\nRemember to put your answer')
    return c[i+2:j]
def toks(s):
    s=s.lower()
    s=re.sub(r'\\[a-z]+','',s)
    s=re.sub(r'[^a-z0-9]+',' ',s)
    return set(w for w in s.split() if len(w)>2)
# unique train questions
seen={}
for r in tt:
    q=train_q(r['prompt'][0]['content'])
    if q not in seen: seen[q]=r['extra_info'].get('problem_id')
train=list(seen)
print('unique train',len(train))
train_toks=[toks(q) for q in train]
# inverted index
inv=collections.defaultdict(list)
for i,ts in enumerate(train_toks):
    for w in ts: inv[w].append(i)
for vr in vt:
    vq=vr['extra_info']['raw_problem']; vts=toks(vq)
    cand=collections.Counter()
    for w in vts:
        for i in inv.get(w,[]): cand[i]+=1
    best=[]
    for i,c in cand.most_common(5):
        j=len(vts & train_toks[i])/len(vts | train_toks[i])
        best.append((round(j,3),train[i][:150]))
    print(vr['data_source'],vr['extra_info']['problem_id'],'|',vr['extra_info']['raw_problem'][:70].replace('\n',' '))
    for b in sorted(best,reverse=True)[:2]: print('    ',b)
EOF
