 cfg['trainer'].update(default_local_dir=str(logs/'checkpoints'),rollout_data_dir=str(logs/'rollouts'),validation_data_dir=str(logs/'fresh_eval'),logger=['console','file'])
 cfg['ray_kwargs']['ray_init']={}
